#include "powder/gpu_clump.hpp"
#include <iostream>
using namespace powder;
void check(bool b,const char* s){if(!b)throw std::runtime_error(s);}
ClumpRunState fixture(){ClumpRunState state;MixingConfig config;config.dt=1e-7;config.duration_s=.0001;config.sample_s=.00001;state.Dt=config.dt;state.World.bodies=mixing_charge(config);MaterialContact m;m.law=ContactLaw::Linear;m.linear={1000,.01,250,.0025,.4};state.World.pair_models={{{0,0},m},{{0,1},m},{{1,1},m}};state.World.wall_models={{0,m},{1,m}};state.World.planes={{1,{0,0,1},0}};state.Mixing.emplace(config,state.World.bodies);state.Backend=make_gpu_backend(state.World);return state;}
int main(){try{auto initial=fixture();std::vector<ClumpRunState> results;for(double hz:{1.,120.}){ClumpWorkerOptions options;options.paced=false;options.batch_steps=200;options.snapshot_hz=hz;ClumpWorker worker(initial,options);worker.single_step();check(worker.snapshot()->steps==1,"single step batched unexpectedly");worker.run();const auto end=std::chrono::steady_clock::now()+std::chrono::seconds(15);while(!worker.snapshot()->finished&&worker.snapshot()->error.empty()&&std::chrono::steady_clock::now()<end)std::this_thread::sleep_for(std::chrono::milliseconds(1));worker.pause();check(worker.snapshot()->error.empty()&&worker.snapshot()->finished,"GPU worker did not finish");auto done=worker.checkpoint();check(done.Steps==1000&&done.Mixing->samples.size()==11,"batch skipped measurement boundary");for(unsigned i=0;i<11;++i)check(done.Mixing->samples[i].step==i*100&&std::abs(done.Mixing->samples[i].time_s-i*.00001)<1e-15,"measurement timestamp");results.push_back(done);worker.reset(initial,options);check(worker.snapshot()->steps==0&&!worker.snapshot()->running,"reset did not stop batch");worker.run();std::this_thread::sleep_for(std::chrono::milliseconds(10));auto start=std::chrono::steady_clock::now();worker.pause();check(std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()<.5,"pause latency exceeded small-scene bound");const auto paused=worker.snapshot()->steps;std::this_thread::sleep_for(std::chrono::milliseconds(5));check(worker.snapshot()->steps==paused,"pause not barrier");}
 auto cpu=initial.World;for(unsigned i=0;i<1000;++i)cpu.step(initial.Dt);for(std::size_t i=0;i<cpu.bodies.size();++i){check(std::abs(cpu.bodies[i].position_m.z-results[0].World.bodies[i].position_m.z)<1e-12,"batched CPU parity");check(results[0].World.bodies[i].position_m.z==results[1].World.bodies[i].position_m.z,"display frequency changed physics");}for(unsigned i=0;i<11;++i){const auto& a=results[0].Mixing->samples[i];const auto& b=results[1].Mixing->samples[i];check(a.mass==b.mass&&a.count==b.count&&a.index==b.index,"display frequency changed measurements");}std::cout<<"PASS batched worker sample boundaries, pause/reset, CPU parity, 1/120 Hz display independence\n";}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
